fun <T, R> List<T>.mapChecked220(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
sealed class Outcome221 {
    data class Success(val payload: String) : Outcome221()
    data object Failure : Outcome221()
}

fun describe221(outcome: Outcome221): String = when (outcome) {
    is Outcome221.Success -> outcome.payload
    Outcome221.Failure -> "failed"
}
